          title: "Python 对照实现：哨兵在 Python 里可以省掉，但道理要讲清",
          code: "# insertion_sorts.py -- 插入类排序的 Python 对照\n# 运行：python insertion_sorts.py\n# 时间复杂度：直接插入 / 折半插入 O(n^2)（最好 O(n)）；希尔 O(n^1.3) 量级\n# 空间复杂度：O(1) 原地排序；稳定性：直接插入、折半插入稳定，希尔不稳定\n\n\ndef insertion_sort(a):\n    \"\"\"直接插入排序。Python 里用 j >= 0 当边界，等价于 C 里 r[0] 哨兵的作用。\"\"\"\n    n = len(a)\n    for i in range(1, n):\n        key = a[i]                # 相当于把 r[i] 存进哨兵 r[0]\n        j = i - 1\n        while j >= 0 and key < a[j]:   # 边界检查 + 关键字比较\n            a[j + 1] = a[j]            # 记录后移一格\n            j -= 1\n        a[j + 1] = key            # 落位\n    return a\n\n\ndef bin_insertion_sort(a):\n    \"\"\"折半插入排序：只在「找插入位置」这一步改用折半查找。\"\"\"\n    n = len(a)\n    for i in range(1, n):\n        key = a[i]\n        low, high = 0, i - 1\n        while low <= high:            # 折半查找插入点\n            mid = (low + high) // 2\n            if key < a[mid]:\n                high = mid - 1\n            else:\n                low = mid + 1         # 相等时走右半区 -> 稳定\n        a[high + 1:i + 1] = [key] + a[high + 1:i]   # 整体后移并落位\n    return a\n\n\ndef shell_sort(a, gaps=None):\n    \"\"\"希尔排序：增量序列必须以便宜的 1 收尾，最后一趟才是真正的全排序。\"\"\"\n    n = len(a)\n    if gaps is None:\n        gaps, g = [], n // 2\n        while g >= 1:\n            gaps.append(g)\n            g //= 2\n    for d in gaps:\n        for i in range(d, n):         # 对「位置相差 d」的每个组做插入排序\n            key = a[i]\n            j = i - d\n            while j >= 0 and key < a[j]:\n                a[j + d] = a[j]\n                j -= d\n            a[j + d] = key\n        print(\"增量 d =\", d, \"一趟后:\", a)\n    return a\n\n\nif __name__ == \"__main__\":\n    A = [49, 38, 65, 97, 76, 13, 27, 49]\n    print(\"原始序列  \", A)\n    print(\"直接插入后\", insertion_sort(A[:]))\n    print(\"折半插入后\", bin_insertion_sort(A[:]))\n    print(\"希尔排序（增量 5, 3, 1）：\")\n    S = [49, 38, 65, 97, 76, 13, 27, 49, 55, 4]\n    shell_sort(S, [5, 3, 1])\n    print(\"希尔排序后\", S)\n"
