          "title": "Python 对照实现：置换-选择排序 + 最小堆 k 路平衡归并",
          "code": "# external_sort.py -- 外部排序的 Python 模拟：置换-选择排序 + k 路平衡归并（多趟）\n# 运行：python external_sort.py\n# 时间复杂度：内部归并的关键字比较次数约等于「记录数 x log2(k 上取整) x 归并趟数」；\n#             外存 I/O 次数 = 2 x 总块数 x 归并趟数，外部排序的总时间通常由 I/O 主导\n# 空间复杂度：k 路归并需要 k 个输入缓冲区（这里用堆模拟）+ 1 个输出缓冲区，堆本身 O(k)\n# 说明：用数组模拟外存文件；heapq 是最小堆，作用与 C 版本里的败者树完全相同\nimport heapq\n\nN = 30\nK = 4\nW = 3\nBLOCK = 3\nDISK = [17, 21, 5, 44, 10, 12, 56, 32, 29, 8, 60, 19, 44, 33, 28, 90,\n        71, 1, 55, 22, 65, 48, 37, 99, 14, 76, 26, 53, 41, 87]\n\n\ndef replacement_selection(seq, w):\n    \"\"\"置换-选择排序：内存工作区容量 w，生成的初始归并段平均长度约为 2w。\"\"\"\n    runs, pool, it = [], [], iter(seq)\n    for _ in range(w):                    # 先把工作区填满\n        try:\n            pool.append(next(it))\n        except StopIteration:\n            break\n    while pool:\n        last, run = float(\"-inf\"), []\n        while True:\n            cand = [x for x in pool if x >= last]     # 只有不小于 last 的记录才能进当前段\n            if not cand:\n                break                                 # 工作区没有可输出的记录 -> 本段结束\n            v = min(cand)\n            run.append(v)\n            last = v\n            pool.remove(v)\n            try:\n                pool.append(next(it))                 # 用文件中的下一条补位\n            except StopIteration:\n                pass\n        runs.append(run)\n    return runs\n\n\ndef kway_merge_heap(runs, k, counter):\n    \"\"\"k 路平衡归并：最小堆里始终只有 k 个排头，每输出一个记录只需 O(log2 k)。\"\"\"\n    heap = [(run[0], i, 0) for i, run in enumerate(runs) if run]\n    heapq.heapify(heap)\n    counter[0] += len(heap)\n    out = []\n    while heap:\n        v, i, j = heapq.heappop(heap)\n        out.append(v)\n        if j + 1 < len(runs[i]):\n            heapq.heappush(heap, (runs[i][j + 1], i, j + 1))\n            counter[0] += 1                  # 一次下沉 / 上升约 log2 k 次比较，这里按 1 次入堆计\n    return out\n\n\ndef kway_merge_naive(runs, k, counter):\n    \"\"\"对照：每一轮固定比较 k-1 次找最小值，不做堆/败者树优化。\"\"\"\n    pos = [0] * len(runs)\n    out = []\n    while True:\n        best = 0\n        done = True\n        key = []\n        for i in range(len(runs)):\n            key.append(runs[i][pos[i]] if pos[i] < len(runs[i]) else float(\"inf\"))\n            if key[i] != float(\"inf\"):\n                done = False\n        if done:\n            break\n        for i in range(1, len(runs)):        # 固定 k-1 次比较\n            counter[0] += 1\n            if key[i] < key[best]:\n                best = i\n        out.append(runs[best][pos[best]])\n        pos[best] += 1\n    return out\n\n\ndef multi_pass(runs, k, merge, counter):\n    \"\"\"完整的多趟平衡归并，返回（有序结果, 趟数, 每趟之后的段长）。\"\"\"\n    runs = [r[:] for r in runs]\n    passes, log = 0, []\n    while len(runs) > 1:\n        nxt = []\n        for s in range(0, len(runs), k):\n            nxt.append(merge(runs[s:s + k], k, counter))\n        runs = nxt\n        passes += 1\n        log.append([len(r) for r in runs])\n    return runs[0], passes, log\n\n\nif __name__ == \"__main__\":\n    blocks = (N + BLOCK - 1) // BLOCK\n    print(\"记录总数\", N, \"，块大小\", BLOCK, \"个记录 =>\", blocks, \"块；内存工作区\", W, \"个记录\")\n\n    runs = replacement_selection(DISK, W)\n    print(\"\\n[阶段一] 置换-选择排序生成\", len(runs), \"个初始归并段，长度\",\n          [len(r) for r in runs], \"，平均长度\", round(N / len(runs), 1),\n          \"（理论平均长度 2W =\", 2 * W, \"）\")\n    for i, r in enumerate(runs):\n        print(\"  归并段\", i + 1, \"：\", r)\n\n    c1 = [0]\n    result, passes, log = multi_pass(runs, K, kway_merge_heap, c1)\n    print(\"\\n[阶段二 A] 用最小堆做\", K, \"路平衡归并：\")\n    for i, l in enumerate(log):\n        print(\"  第\", i + 1, \"趟后剩\", len(l), \"段，长度\", l)\n    print(\"  最终有序输出：\", result)\n    print(\"  最少归并趟数 S = log_\" + str(K), len(runs), \"上取整 =\", passes, \"趟\")\n\n    c2 = [0]\n    _, _, _ = multi_pass(runs, K, kway_merge_naive, c2)\n    print(\"\\n[阶段二 B] 顺序扫描法重跑同一组数据：比较次数\", c2[0], \"（每轮固定比较 k-1 =\", K - 1, \"次）\")\n    print(\"  堆/败者树方案把它降到了\", c1[0], \"量级\")\n\n    print(\"\\n[I/O 估算] 每趟归并读写各\", blocks, \"块 => 每趟\", 2 * blocks,\n          \"块 I/O，\", passes, \"趟共\", 2 * blocks * passes, \"块 I/O\")\n"
