          "code": "# tree_hash_search.py -- 树表查找与散列查找的 Python 对照\n# 运行：python tree_hash_search.py\n# 时间复杂度：二叉排序树 平均 O(log2 n)、最坏 O(n)；AVL O(log2 n)；m 阶 B 树 O(log_m n)；\n#             散列表 平均 O(1)、最坏 O(n)\n# 空间复杂度：树 O(n)；散列表 O(m)\n# 说明：散列的 ASL 与哈希函数、冲突处理方法、装填因子 alpha = n / m 都有关\n\n\nclass BST:\n    \"\"\"二叉排序树：左子树全部小于根，右子树全部大于根。\"\"\"\n\n    def __init__(self):\n        self.key = None\n        self.l = self.r = None\n        self.n = 0\n\n    def insert(self, key):\n        if self.key is None:\n            self.key, self.n = key, 1\n            return\n        if key < self.key:\n            if self.l is None:\n                self.l = BST()\n            self.l.insert(key)\n        elif key > self.key:\n            if self.r is None:\n                self.r = BST()\n            self.r.insert(key)\n        self.n = 1 + (self.l.n if self.l else 0) + (self.r.n if self.r else 0)\n\n    def search(self, key):\n        \"\"\"返回比较次数，找不到返回 -1。\"\"\"\n        cmp, t = 0, self\n        while t is not None and t.key is not None:\n            cmp += 1\n            if key == t.key:\n                return cmp\n            t = t.l if key < t.key else t.r\n        return -cmp                     # 负数表示失败，绝对值是比较次数\n\n    def depth_sum(self, depth=1):\n        \"\"\"返回 (层数总和, 结点数, 最大层数)，用来算 ASL。\"\"\"\n        if self.key is None:\n            return 0, 0, 0\n        sl, nl, dl = self.l.depth_sum(depth + 1) if self.l else (0, 0, 0)\n        sr, nr, dr = self.r.depth_sum(depth + 1) if self.r else (0, 0, 0)\n        return depth + sl + sr, 1 + nl + nr, max(depth, dl, dr)\n\n\nclass AVL:\n    \"\"\"平衡二叉树：任一结点左右子树高度差不超过 1，插入时用四种旋转修复。\"\"\"\n\n    def __init__(self, key):\n        self.key, self.h = key, 1\n        self.l = self.r = None\n\n\ndef ah(t):\n    return t.h if t else 0\n\n\ndef update(t):\n    t.h = max(ah(t.l), ah(t.r)) + 1\n    return t\n\n\ndef rot_ll(y):                      # 右单旋（LL 型）\n    x = y.l\n    y.l = x.r\n    x.r = y\n    update(y)\n    return update(x)\n\n\ndef rot_rr(x):                      # 左单旋（RR 型）\n    y = x.r\n    x.r = y.l\n    y.l = x\n    update(x)\n    return update(y)\n\n\ndef avl_insert(t, key, rot):\n    if t is None:\n        return AVL(key)\n    if key < t.key:\n        t.l = avl_insert(t.l, key, rot)\n    elif key > t.key:\n        t.r = avl_insert(t.r, key, rot)\n    else:\n        return t\n    update(t)\n    bf = ah(t.l) - ah(t.r)\n    if bf > 1 and key < t.l.key:\n        rot[0] += 1\n        return rot_ll(t)\n    if bf < -1 and key > t.r.key:\n        rot[0] += 1\n        return rot_rr(t)\n    if bf > 1 and key > t.l.key:\n        rot[0] += 1\n        t.l = rot_rr(t.l)\n        return rot_ll(t)\n    if bf < -1 and key < t.r.key:\n        rot[0] += 1\n        t.r = rot_ll(t.r)\n        return rot_rr(t)\n    return t\n\n\ndef avl_pre(t, out):\n    if t is None:\n        return\n    out.append(t.key)\n    avl_pre(t.l, out)\n    avl_pre(t.r, out)\n\n\nclass BTreeNode:\n    \"\"\"m 阶 B 树结点：最多 m-1 个关键字、m 棵子树。\"\"\"\n\n    def __init__(self):\n        self.keys = []\n        self.children = []\n\n\ndef bt_split(parent, i):\n    full = parent.children[i]\n    mid = len(full.keys) // 2\n    up = full.keys[mid]\n    right = BTreeNode()\n    right.keys = full.keys[mid + 1:]\n    right.children = full.children[mid + 1:] if full.children else []\n    left = BTreeNode()\n    left.keys = full.keys[:mid]\n    left.children = full.children[:mid + 1] if full.children else []\n    parent.keys.insert(i, up)\n    parent.children[i:i + 1] = [left, right]\n    return up, left.keys, right.keys\n\n\ndef bt_insert(root, key, m):\n    if root is None:\n        root = BTreeNode()\n    _bt_insert_nonfull(root, key, m)\n    if len(root.keys) >= m:                # 根溢出 -> 长高一层\n        nr = BTreeNode()\n        nr.children = [root]\n        up, lk, rk = bt_split(nr, 0)\n        return nr, True, (up, lk, rk)\n    return root, False, None\n\n\ndef _bt_insert_nonfull(node, key, m):\n    if not node.children:                  # 叶子结点\n        node.keys.append(key)\n        node.keys.sort()\n        return\n    i = 0\n    while i < len(node.keys) and key > node.keys[i]:\n        i += 1\n    _bt_insert_nonfull(node.children[i], key, m)\n    if len(node.children[i].keys) >= m:\n        bt_split(node, i)\n\n\ndef bt_print(t, depth=0):\n    if t is None:\n        return\n    print(\"    \" * depth + \"[\" + \" \".join(str(k) for k in t.keys) + \"]\")\n    for c in t.children:\n        bt_print(c, depth + 1)\n\n\ndef bt_height(t):\n    if t is None:\n        return 0\n    if not t.children:\n        return 1\n    return 1 + bt_height(t.children[0])\n\n\ndef hash_linear_probe(keys, m):\n    \"\"\"线性探测法建散列表，返回 (表, 各关键字比较次数)。\"\"\"\n    table = [None] * m\n    cmps = []\n    for k in keys:\n        i, c = k % m, 1\n        while table[i] is not None:\n            i = (i + 1) % m\n            c += 1\n        table[i] = k\n        cmps.append(c)\n    return table, cmps\n\n\ndef hash_fail_asl(table):\n    \"\"\"ASL失败：从每个位置出发探测到空位所需的比较次数，再取平均。\"\"\"\n    m, total = len(table), 0\n    for i in range(m):\n        j, c = i, 1\n        while table[j] is not None:\n            j = (j + 1) % m\n            c += 1\n        total += c\n    return total / m\n\n\nif __name__ == \"__main__\":\n    print(\"=========== 1. 二叉排序树 ===========\")\n    b = BST()\n    for k in (45, 24, 53, 12, 37, 93):\n        b.insert(k)\n    s, n, d = b.depth_sum()\n    print(\"  依次插入 45 24 53 12 37 93：结点数\", n, \"层数总和\", s,\n          \"ASL成功 =\", s, \"/\", n, \"=\", round(s / n, 4), \"树高\", d)\n    print(\"  查找 37：比较\", b.search(37), \"次成功\")\n    r = b.search(50)\n    print(\"  查找 50：比较\", -r, \"次后失败\")\n\n    print(\"\\n=========== 2. 平衡二叉树 AVL ===========\")\n    av, rot = None, [0]\n    for k in range(1, 11):\n        av = avl_insert(av, k, rot)\n        out = []\n        avl_pre(av, out)\n        print(\"    插入\", k, \"后 高度 =\", av.h, \"，先序遍历：\", out)\n    print(\"  共发生旋转\", rot[0], \"次，最终高度\", av.h, \"（10 个结点退化成单链时高度会是 10）\")\n\n    print(\"\\n=========== 3. B 树（3 阶）===========\")\n    M, root = 3, None\n    for k in range(1, 11):\n        root, grew, info = bt_insert(root, k, M)\n        print(\"  插入\", k, \"：\")\n        if info:\n            print(\"      分裂：中间关键字\", info[0], \"上移，左子\", info[1], \"右子\", info[2])\n        bt_print(root, 2)\n    h = bt_height(root)\n    print(\"  最终树高\", h, \"层（不含失败结点），含 10 个关键字\")\n    print(\"  按公式：\", M, \"阶 B 树高\", h, \"层时最多容纳 M 的 h 次方 - 1 =\", M ** h - 1, \"个关键字\")\n\n    print(\"\\n=========== 4. 散列表（线性探测）===========\")\n    KEYS = [7, 8, 30, 11, 18, 9, 14]\n    table, cmps = hash_linear_probe(KEYS, 11)\n    print(\"  表长 m = 11，H(key) = key mod 11，依次插入\", KEYS)\n    for k, c in zip(KEYS, cmps):\n        print(\"  插入\", k, \"：H =\", k % 11, \"，比较\", c, \"次\")\n    print(\"  散列表：\", [\"-\" if v is None else v for v in table])\n    print(\"  ASL成功 =\", sum(cmps), \"/\", len(KEYS), \"=\", round(sum(cmps) / len(KEYS), 4),\n          \"；装填因子 alpha = 7/11 =\", round(7 / 11, 4))\n    print(\"  ASL失败 =\", round(hash_fail_asl(table), 4))\n"
